contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(c).balance;

        bool reverted1;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }

        uint256 balAfter1 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherAfter1 = address(c).balance;

        bool reverted2;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }

        uint256 balAfter2 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherAfter2 = address(c).balance;

        assert(!reverted1 && !reverted2
            && balAfter1 == balBefore && balAfter2 == balBefore
            && etherAfter1 == etherBefore && etherAfter2 == etherBefore);
    }

    receive() external payable {}
}

