pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint etherBefore = address(c).balance;
        bool reverted1;
        try c.Initialized() { reverted1 = false; } catch { reverted1 = true; }
        uint256 balAfter1;
        try c.balances(address(this)) returns (uint256 __r) { balAfter1 = __r; } catch { return; }
        uint etherAfter1 = address(c).balance;
        bool reverted2;
        try c.Initialized() { reverted2 = false; } catch { reverted2 = true; }
        uint256 balAfter2;
        try c.balances(address(this)) returns (uint256 __r) { balAfter2 = __r; } catch { return; }
        uint etherAfter2 = address(c).balance;
        assertTrue(!reverted1 && !reverted2
            && balAfter1 == balBefore && balAfter2 == balBefore
            && etherAfter1 == etherBefore && etherAfter2 == etherBefore);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
